void fn0() {
  List<String> setWords = ['hello', 'world', 'set', 'map', 'word'];
  String target = 'word';

  List<int> manhattanDist(String s) {
    List<int> res = List.filled(26, -1);
    for (int i = 0; i < s.length; i++) {
      res[s.codeUnitAt(i) - 97] = i;
    }
    return res;
  }

  int minManhattan(List<int> res) {
    int minVal = 26;
    for (int v in res) {
      if (v >= 0 && v < minVal) minVal = v;
    }
    return minVal;
  }

  List<int> query(String s) {
    List<int> dist = manhattanDist(s);
    return List.generate(26, (int i) => dist[i] == -1 ? -1 : i);
  }

  Set<String> seen = {};
  for (String s in setWords) {
    if (s.length == target.length) {
      seen.add(s);
    }
  }

  Map<String, List<int>> pref = {};
  for (String s in setWords) {
    if (s.length == target.length) {
      pref[s] = [0];
    }
  }

  bool bfs(String s) {
    if (seen.contains(s)) return true;

    List<int> dist = query(s);

    if (dist.isEmpty) {
      return false;
    }

    List<int> q = [dist[0]];

    while (q.isNotEmpty) {
      int u = q.removeAt(0);
      String word = s + String.fromCharCode(97 + u);

      if (seen.contains(word)) {
        return true;
      }

      pref[word] = [u]
        ..addAll(pref[s] ?? []);

      List<int> nextDist = [];
      for (int v in pref[s] ?? []) {
        nextDist.add(u + v);
      }

      if (nextDist.isNotEmpty) {
        q.add(nextDist[0]);
      }
    }

    return false;
  }

  bool found = false;

  for (String s in setWords) {
    if (s.length == target.length && !seen.contains(s)) {
      if (bfs(s)) {
        found = true;
        break;
      }
    }
  }

  print(found ? 'Found' : 'Not Found');

  if (found) {
    List<int> dist = manhattanDist(target);
    int minDist = minManhattan(dist);
    print('Min distance: $minDist');

    for (String s in setWords) {
      if (s.length == target.length && !seen.contains(s)) {
        List<int> queryDist = query(s);
        if (minManhattan(queryDist) == minDist) {
          print(s);
        }
      }
    }
  }
}

