      }
    }
  }

  colEntries.sort((a, b) {
    int byCol = a.value.compareTo(b.value);
    if (byCol != 0) {
      return byCol;
    }
    return a.key.compareTo(b.key);
  });

  print('Row Entries:');
  for (var entry in rowEntries) {
    print('${entry.key}: ${entry.value}');
  }

  print('Column Entries:');
  for (var entry in colEntries) {
    print('${entry.key}: ${entry.value}');
  }
}

