@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final numbers = [1, 2, 3, 4, 5];

  List<String> combine = (String prefix, List<int> items) {
    if (items.isEmpty) {
      return [prefix];
    }
    final Map<String, List<List<int>>> memo = <String, List<List<int>>>{};
    List<String> result = [];
    void recurse(String prefix, List<int> remaining) {
      if (remaining.isEmpty) {
        result.add(prefix);
        return;
      }
      if (memo.containsKey(prefix)) {
        final List<List<int>> existing = memo[prefix]!;
        for (final List<int> item in existing) {
          recurse(prefix + '$item', remaining.sublist(item.length));
        }
        return;
      }
      final Set<int> used = <int>{};
      for (final int i = 0; i < item.length; i++) {
        used.add(i);
      }
      for (final int i = 0; i < used.length; i++) {
        final int idx = used.index(i);
        final int item = remaining[idx];
        final List<List<int>> sub = combine(prefix + '$item', remaining.sublist(item.length));
        for (final String subPrefix in sub) {
          memo[prefix + '$item'] = sub;
          result.add(subPrefix);
        }
      }
    }
    recurse('', numbers);
    return result;
  };

  final List<String> combinations = combine('', numbers);

  for (final String combo in combinations) {
    print(combo);
  }

  final Map<String, int> frequency = <String, int>{};
  for (final String combo in combinations) {
    frequency[combo] = (frequency[combo] ?? 0) + 1;
  }

  print('Frequency of each combination:');
  for (final String combo in combinations) {
    print('$combo: ${frequency[combo]}');
  }
}

