Map<String, int> fn0(List<String> entries, List<int> amounts) {
  final cents = <int>[];
  final rounded = <int>[];
  final labels = <String>[];
  for (int i = 0; i < entries.length; i++) {
    final amount = amounts[i];
    if (amount < 0) {
      cents.add(0);
      rounded.add(0);
      labels.add('-');
    } else {
      final roundedAmount = ((amount * 100) + 5) ~/ 100;
      if (roundedAmount < 0) {
        roundedAmount = 0;
      }
      if (roundedAmount > 100) {
        roundedAmount = 100;
      }
      cents.add(roundedAmount);
      rounded.add(roundedAmount);
      labels.add('$i:${roundedAmount > amount ? '+' : ''}$amount->${roundedAmount - amount}');
    }
  }
  if (rounded.isEmpty) return {'-1': 0};
  final r = (rounded[0] == 0) ? rounded[1] : rounded[0];
  final l = labels[0];
  int carry = 0;
  for (int i = 1; i < rounded.length; i++) {
    final a = rounded[i];
    final b = r;
    if (a == b) {
      carry = carry < 0 ? 0 : carry;
    } else {
      final diff = a - b;
      if (diff.abs() <= 1) {
        carry = carry + diff;
      } else {
        carry += diff > 0 ? 1 : -1;
      }
    }
    r = b + carry;
    l += '$i:${r > b ? '+' : ''}$b->${r - b}';
  }
  return {'$l': carry};
}

