Map<String, int> fn0(List<String> commands, int maxStackDepth, int minWindowLength, int minGap) {
  final Map<String, int> results = <String, int>{};
  final List<int> stack = <int>[];
  final List<int> history = <int>[];

  void push(int value) {
    stack.add(value);
    history.add(0);
  }

  int pop() {
    if (stack.isEmpty) return 0;
    final int top = stack.removeLast();
    history.add(top);
    return top;
  }

  void undo() {
    if (history.isEmpty) return;
    final int last = history.removeLast();
    if (last == 0) {
      stack.add(0);
    } else {
      stack[stack.length - 1] = last;
    }
  }

  for (final String cmd in commands) {
    if (cmd == '<') {
      if (stack.isNotEmpty) {
        push(pop());
      }
    } else if (cmd == '!') {
      undo();
    } else if (cmd == '^') {
      if (stack.isNotEmpty) {
        push(pop());
      }
    } else {
      final int val = int.parse(cmd);
      if (val >= 0) {
        push(val);
      } else if (stack.length >= minWindowLength) {
        final int windowSum = stack.reduce((a, b) => a + b);
        if (val == windowSum) {
          results['$windowSum@${stack.length}'] = stack.length;
        }
      }
    }
  }

  for (final entry in results.entries) {
    if (entry.value <= maxStackDepth) {
      break;
    }
    final int sum = entry.key.split('@')[0];
    final int count = entry.value;
    final List<int> sorted = List<int>.of(stack);
    sorted.sort();
    int i = 0;
    while (i < sorted.length) {
      final int current = sorted[i];
      final int left = i;
      while (i < sorted.length && sorted[i] == current) {
        i++;
      }
      final int right = i - 1;
      if (left > 0 && sorted[left] + sorted[right] >= sum && right - left + 1 >= minGap) {
        results[entry.key] = count;
        break;
      }
    }
  }
  return results;
}

