        history.add(['move', 0]);
        continue;
      }
      final dx = int.parse(parts[1]);
      final dy = int.parse(parts[2]);
      x += dx;
      y += dy;
      history.add(['move', '$dx,$dy']);
    } else if (parts[0] == 'undo') {
      if (history.isEmpty) {
        history.add(['undo', 0]);
        continue;
      }
      final last = history.removeLast();
      if (last[0] == 'push') {
        stack.removeLast();
