    editsFreq[e] = (editsFreq[e] ?? UNORDERED) - 1;
  }
  final Map<String, int> freq = {};
  for (int i = 0; i < word.length; i++) {
    final String ch = word[i];
    freq[ch] = (freq[ch] ?? 0) + 1;
  }
  int score = 0;
  for (int i = 0; i < word.length; i++) {
    final String ch = word[i];
    final int count = freq[ch]!;
    if (editsFreq.containsKey(ch)) {
      final int freq = editsFreq[ch]!;
      if (count == 1 && freq == 0) {
        score += 2;
      } else if (count > 1 && freq > 0) {
        score += 1;
      } else if (count == 1 && freq > 0) {
        score -= 1;
      }
    }
  }
  return score == 0 ? {} : freq;
}

