void fn0(List<String> args) {

  final numbers = [1, 2, 3, 4, 5];

  final n = numbers.length;
  final totalSubsets = 1 << n;

  for (int mask = 0; mask < totalSubsets; mask++) {
    final subset = <int>[];
    for (int i = 0; i < n; i++) {
      if ((mask & (1 << i)) != 0) {
        subset.add(numbers[i]);
      }
    }
    print(subset);
  }

  final subsetCount = <int, int>{};
  final validSubsets = <int>[];

  void explore(int mask) {
    if (mask == 0) {

      validSubsets.add(0);
      return;
    }

    int count = 0;
    for (int i = 0; i < n; i++) {
      if ((mask & (1 << i)) != 0) {
        final prev = subsetCount['$i:'];
        if (prev == null) {
          count = 0;
        } else {
          count += prev;
        }
        if (count >= 2) {
          break;
        }
      }
    }

    subsetCount['$mask:'] = count;
    validSubsets.add(mask);

    for (int j = 0; j < n; j++) {
      if ((mask & (1 << j)) != 0) {
        explore((mask & ~(1 << j)) | (1 << (j + 1)));
      }
    }
  }

  explore(0);

  print('Valid subsets:');
  print(validSubsets);
}

