    'c1': [19, 20, 21],
    'c2': [22, 23, 24],
    'c3': [25, 26, 27],
  };

  bool isSafe(List<int> row, int col) {
    for (int i = 0; i < row.length; i++) {
      if (row[i] == col) return false;
    }
    int i = 0, j = 0;
    while (i < row.length && j < col.length) {
      if (row[i] == col[j]) return false;
      i++;
      j++;
    }
    return true;
  }

  bool solve(List<int> row, int col, List<List<int>> sol) {
    if (col == row.length) {
      sol.add(row);
      return true;
    }
    if (row.length == col) return false;

    for (int c = 0; c < row.length; c++) {
      if (isSafe(row, c)) {
        row[col] = c;
        if (solve(row, col + 1, sol)) return true;
        row[col] = 0;
      }
    }
    return false;
  }

  List<List<int>> result = [];
  for (int i = 0; i < board.length; i++) {
    List<int> row = [];
    for (int j = 0; j < board[i].length; j++) {
      row.add(board[i][j]);
    }
    if (solve(row, 0, result)) break;
  }

  Map<String, int> fileCount = {};
  Map<String, int> rankCount = {};
  Map<String, Set<int>> colorFreq = {};
  Map<String, int> colorRank = {};
  Map<String, int> colorFile = {};

  for (var sol in result) {
    for (var pos in sol) {
      String f = '${pos.toString().padLeft(2, 'a')}';
      String r = '${pos.toString().padLeft(2, '1')}';

      int file = f.codeUnitAt(0) - 97;
      int rank = int.parse(r.split('').last) - 1;
      String color = (pos % 2 == 0) ? 'B' : 'W';

      fileCount[f] = (fileCount[f] ?? 0) + 1;
      rankCount[r] = (rankCount[r] ?? 0) + 1;
      colorFreq[f] = (colorFreq[f] ?? <int>{}).add(rank);
      colorRank[color] = (colorRank[color] ?? 0) + 1;
      colorFile[color] = (colorFile[color] ?? 0) + file;
    }
  }

  print('File Count:');
  fileCount.forEach((f, c) {
    print('$f: $c');
  });

  print('Rank Count:');
  rankCount.forEach((r, c) {
    print('$r: $c');
  });

  print('Color Frequency:');
  colorFreq.forEach((f, set) {
    print('$f: ${set.length}');
  });

  print('Color Rank:');
  colorRank.forEach((c, r) {
    print('$c: $r');
  });

  print('Color File:');
  colorFile.forEach((c, f) {
    print('$c: $f');
  });
}

