List<String> fn0(String chart) {
  final tally = <String, int>{};
  final candidates = <String>[];
  var totalVotes = 0;

  if (chart.isEmpty) {
    return candidates;
  }

  for (var i = 0; i < chart.length; i++) {
    final ch = chart[i];
    if (ch == ' ') {
      continue;
    }

    final row = i ~/ chart.length;
    final col = i % chart.length;
    if (ch == '=') {
      continue;
    }

    if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
      final count = int.parse(ch);
      if (count <= 0) {
        continue;
      }

      var candidateName = '';
      for (var j = col - 1; j >= 0; j--) {
        final c = chart[j];
        if (c == '#') {
          break;
        }
        candidateName += c;
      }

      final prefix = '${candidateName}_$row-$col:$count';
      tally[prefix] = (tally[prefix] ?? 0) + count;
      totalVotes += count;
      continue;
    }

    final prefix = '$ch:$row-$col';
    tally[prefix] = (tally[prefix] ?? 0) + 1;
    totalVotes += 1;

    if (ch == '#') {
      candidates.add(prefix);
    }
  }

  if (totalVotes == 0) {
    return candidates;
  }

  var margin = 0;
  var tie = false;
  var bestPrefix = '';

  for (final entry in tally.entries) {
    final count = entry.value;
    if (count > 0) {
      margin += count;
    } else if (count < 0) {
      margin -= count;
    }

    if (!tie && margin > 0) {
      bestPrefix = entry.key;
    }

    if (count == 0 && !tie) {
      continue;
    }

    final key = '${bestPrefix}_$row-$col:$count';
    tally[key] = (tally[key] ?? 0) - 1;

    if (tally[key] == 0) {
      tally.remove(key);
    }
  }

  candidates.sort();
  return candidates;
}

