    if (last != null) {
      tokens.add(last);
      runs.add(0);
    }
    for (int k = 0; k < tokens.length; k++) {
      for (int m = 1; m <= runs[k]; m++) {
        edits.add(tokens[k] + (m == 1 ? '' : '${m - 1}'));
