  int state = 0;
  bool patternFound = false;

  for (int i = 0; i < pattern.length; i++) {
    String c = pattern[i];
    if (state == 0) {
      if (c == '.') {
        state = 1;
      } else if (c != '*') {
        return matches;
      }
    } else if (state == 1) {
      if (c == '*') {
        state = 2;
      } else if (c == '.') {
        state = 1;
      } else {
        return matches;
      }
    } else if (state == 2) {
      if (c == '*') {
        state = 2;
      } else if (c != '.') {
        return matches;
      }
    }
  }

  if (state == 0) {
