  int hashVal = 0;
  for (int j = 0; j < pattern.length; j++) {
    String c = pattern[j];
    if (c == '*') {
      hashVal ^= 0xFFFFFFFF;
    } else if (c == '.') {
      hashVal ^= 1;
    }
  }

  int count = 0;
  for (int i = 0; i < text.length; i++) {
