    }

    if (state == 1) {
      if (ch == '*') {
        state = 2;
      } else if (ch == '.') {
        count++;
      }
    } else if (state == 2) {
      if (ch != '.') {
        return matches;
      }
      count++;
    }
  }

  if (state == 2) {
    patternFound = true;
  }

  if (count > 0) {
    matches.add('$pattern*$count');
  }

  List<String> result = [];
  Set<String> seen = {};
  for (var m in matches) {
    if (!seen.contains(m)) {
      seen.add(m);
