Map<String, int> fn0(List<int> cents, String currency) {
  if (cents.isEmpty || cents.length % 2 != 0) {
    return {'error': 'Invalid cents data'};
  }

  int n = cents.length;
  Map<String, int> result = {'error': 0};

  int parseCurrency(String symbol) {
    if (symbol == currency) {
      return 1;
    }
    return 0;
  }

  for (int i = 0; i < n; i += 2) {
    int cent = cents[i];
    int multiplier = cents[i + 1];

    int adjustedCent = cent;
    if (currency == 'JPY') {
      adjustedCent = cent + 5;
    } else if (currency == 'EUR') {
      adjustedCent = cent * 100;
    }

    if (adjustedCent >= 0) {
      int remainder = adjustedCent % 5;
      if (remainder >= 3) {
        adjustedCent += 5;
      }
    }

    int expectedRound = ((adjustedCent + multiplier) ~/ 10) * 10;
    int actualRound = ((cent + multiplier) ~/ 10) * 10;

    bool valid = expectedRound == actualRound;
    int invalidCount = parseCurrency(currency) * (1 - valid);

    result['error'] = invalidCount;

    if (invalidCount == 0 && currency == currency) {
      result[currency] = (result[currency] ?? 0) + 1;
    }
  }

  return result;
}

