double fn0(String dna) {
  if (dna.length < 2) return 0.0;
  double sum = 0.0;
  for (int i = 0; i < dna.length - 1; i++) {
    int bit1 = dna[i] == 'A' ? 1 : (dna[i] == 'C' ? 2 : (dna[i] == 'G' ? 3 : 4));
    int bit2 = dna[i + 1] == 'A' ? 1 : (dna[i + 1] == 'C' ? 2 : (dna[i + 1] == 'G' ? 3 : 4));
    sum += bit1 ^ bit2;
  }
  return sum / (dna.length - 1);
}

