class Point {
  final double x, y;
  const Point(this.x, this.y);

  const Point.origin() : this(0, 0);

  const Point.unit() : this(1, 1);

  const Point.random() : this(
        Random(0).nextDouble() * 2 - 1,
        Random(0).nextDouble() * 2 - 1,
      );

  @override
  String toString() => '($x, $y)';

  const Point.distance(const Point p) : this(
        (x - p.x).abs(),
        (y - p.y).abs(),
      );

  const Point.mid(const Point p) : this((x + p.x) / 2, (y + p.y) / 2);

  const Point.project(const Point p, double t) : this(t * p.x + (1 - t) * x, t * p.y + (1 - t) * y);

  const Point.refl(const Point p) : this(2 * p.x - x, 2 * p.y - y);

  const Point.reflect(const Point p, const Point normal) : this(
        x + 2 * normal.x * (p.x - x) + 2 * normal.y * (p.y - y),
        y + 2 * normal.x * (p.x - x) + 2 * normal.y * (p.y - y),
      );

  const Point.rotate(
    const Point p,
    double angle,
  ) : this(
        p.x * cos(angle) - p.y * sin(angle),
        p.x * sin(angle) + p.y * cos(angle),
      );

  const Point.expand(const Point p, double factor) : this(p.x * factor, p.y * factor);

  const Point.lerp(const Point a, const Point b, double t) : this(
        a.x + t * (b.x - a.x),
        a.y + t * (b.y - a.y),
      );

  const Point.centroid(const Point a, const Point b) : this(
        (a.x + b.x) / 2,
        (a.y + b.y) / 2,
      );
}

class Circle {
  final double r;
  final Point o;
  const Circle(this.r, this.o);

  @override
  String toString() => 'Circle[$r, ${o.toString()}]';

  const Circle.unit() : this(1, Point.unit());

  const Circle.origin() : this(1, Point.origin());

  const Circle.random() : this(
        Random(0).nextDouble() * 2,
        Point.random(),
      );

  const Circle.distance(const Point p) : this(
        (p.x - o.x).abs() + (p.y - o.y).abs(),
        o,
      );

  const Circle.contains(const Point p) =>
      r > 0 && Circle.distance(p) <= r;

  const Circle.intersect(const Circle c) {
    if (r <= 0 || c.r <= 0) return const Circle.empty();
    final dist = (o.x - c.o.x).abs() + (o.y - c.o.y).abs();
    return dist <= r + c.r ? Circle(
          r + c.r,
          Point.lerp(o, c.o, dist / (r + c.r)),
        ) : const Circle.empty();
  }

  const Circle.empty() : this(0, Point.origin());
}

class Ray {
  final Point o;
  final double d;
  const Ray(this.o, this.d);

  @override
  String toString() => 'Ray[$o, $d)';

  const Ray.origin() : this(Point.origin(), 0);

  const Ray.unit() : this(Point.unit(), 1);

  const Ray.random() : this(Point.random(), Random(0).nextDouble() * 2);

  const Ray.distance(const Point p) =>
      Ray.intersect(Ray.origin()
          .expand(p, (o, d) => Ray.origin().translate(o, d))
          .reflect(p));

  const Ray.reflect(const Point p) =>
      Ray.intersect(Ray.origin()
          .reflect(p, const Point.unit())
          .expand(p, (o, d) => Ray.origin().translate(o, d)));

  const Ray.translate(const Point p, double d) =>
      Ray.intersect(Ray.origin().translate(p, d));

  const Ray.distanceTo(const Ray r) =>
      Ray.intersect(r) != const Ray.empty() ? r.d : r.r.abs() + (o.x - r.o.x).abs() + (o.y - r.o.y).abs();
}

class Segment {
  final Point o, p;
  const Segment(this.o, this.p);

  @override
  String toString() => 'Segment[$o, $p)';

  const Segment.origin() : this(Point.origin(), Point.unit());

  const Segment.unit() : this(Point.unit(), Point.unit());

  const Segment.random() : this(
        Point.random(),
        Point.random().translate(o, (p.x - o.x) * Random(0).nextDouble() - (p.y - o.y) * Random(0).nextDouble()),
      );

  const Segment.distance(const Point p) =>
      Segment.distanceTo(Ray.distance(p));

  const Segment.intersect(const Segment s) {
    if (s.o == o || s.p == o) return const Segment.empty();
    if (s.o == p || s.p == p) return s;
    if (s.o.y == o.y) {
      final t = (o.x - s.o.x) / (s.o.x - s.p.x);
      if (t > 0 && t < 1) return Segment(o, Point.lerp(o, p, t));
    } else if (s.o.x == o.x) {
      final t = (o.y - s.o.y) / (s.o.y - s.p.y);
      if (t > 0 && t < 1) return Segment(o, Point.lerp(o, p, t));
    }
    return const Segment.empty();
  }

  const Segment.empty() : this(Point.origin(), Point.unit());
}

