import 'dart:convert';
class Vector {
  final List<double> components;

  Vector(this.components);

  Vector.zero() : this([0.0, 0.0, 0.0]);

  Vector.unit() : this([1.0, 1.0, 1.0]);

  Vector.random() : this([
        Random(0).nextDouble() * 2 - 1.0,
        Random(0).nextDouble() * 2 - 1.0,
        Random(0).nextDouble() * 2 - 1.0
      ]);

  Vector.random(Random rng) : this([
        rng.nextDouble() * 2 - 1.0,
        rng.nextDouble() * 2 - 1.0,
        rng.nextDouble() * 2 - 1.0
      ]);

  Vector.all(double val) : this([val, val, val]);

  Vector.allZero() : this([0.0, 0.0, 0.0]);

  Vector.allUnit() : this([1.0, 1.0, 1.0]);

  double dot(Vector other) =>
      components[0] * other.components[0] + components[1] * other.components[1] + components[2] * other.components[2];

  double norm() => components.reduce((a, b) => a + b);

  Vector normalized() {
    final double n = norm();
    return Vector(
        components.map((c) => c / n).toList());
  }

  Vector.squared(Vector other) {
    final double dx = components[0] - other.components[0];
    final double dy = components[1] - other.components[1];
    final double dz = components[2] - other.components[2];
    return Vector([dx * dx, dy * dy, dz * dz]);
  }

  Vector.sum(Vector other) {
    return Vector([components[0] + other.components[0], components[1] + other.components[1], components[2] + other.components[2]]);
  }

  Vector.mul(double scalar) {
    return Vector(components.map((c) => c * scalar).toList());
  }

  Vector.rotate(double theta) {
    final double cosTheta =
        cos(theta.abs().isFinite() ? theta.abs() : 0.0), sinTheta =
        sin(theta.abs().isFinite() ? theta.abs() : 0.0);
    final Vector out = Vector.allZero();
    out.components[0] = components[0] * cosTheta - components[1] * sinTheta;
    out.components[1] = components[0] * sinTheta + components[1] * cosTheta;
    out.components[2] = components[2];
    return out;
  }

  @override
  String toString() {
    return 'Vector($components)';
  }
}

