  dp[0][0] = 0;

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (i == 0 && j == 0) continue;

      String current = '';
      for (int k = i; k >= 1; k--) {
        String row = ''.padRight(k);
