      }

      int cost = (current == next) ? 0 : 1;
      int total = dp[i - 1][j - 1] + cost;

      if (i > 0) {
        for (int s = 0; s <= 1; s++) {
          int prevCost = s == 1 ? 1 : 0;
          dp[i][j] = dp[i][j] < total + prevCost ? dp[i][j] : total + prevCost;
        }
      } else {
        dp[i][j] = total;
      }
    }
  }

  int answer = dp[n - 1][m - 1];

  if (answer == INF) {
    print('Impossible');
  } else {
