    List<List<int>> queue = [start];
    int size = 1;
    parent['$row,$col'] = null;
    bool found = false;

    while (size > 0) {
      List<int> cell = queue.removeAt(0);
      int r = cell[0], c = cell[1];
      if ((r >= 0 && r < end[0] && c >= 0 && c < end[1]) && !walls[r * end[1] + c]) {
