void fn0() {
  final Set<int> items = {1, 2, 3};
  final int capacity = 3;
  final List<String> combos = [];

  void backtrack(int start, int load, Set<int> selected) {
    if (load == capacity) {
      bool unique = true;
      for (final item in selected) {
        for (final other in selected) {
          if (item == other) {
            unique = false;
            break;
          }
        }
      }
      if (unique) {
        combos.add('${selected.join(', ')}: ${load}');
        return;
      }
    }

    for (int i = start; i < items.length; i++) {
      final int item = items[i];
      if (load + item <= capacity) {
        selected.add(item);
        backtrack(i + 1, load + item, selected);
        selected.remove(item);
      }
    }
  }

  Set<int> selected = {};
  backtrack(0, 0, selected);

  selected.sort((a, b) {
    final Map<int, int> aMap = items.where((e) => e == a).toMap();
    final Map<int, int> bMap = items.where((e) => e == b).toMap();
    int cmp = aMap[capacity]!.compareTo(bMap[capacity]!);
    if (cmp != 0) return cmp;
    cmp = aMap[capacity - 1]!.compareTo(bMap[capacity - 1]!);
    if (cmp != 0) return cmp;
    return aMap[capacity - 2]!.compareTo(bMap[capacity - 2]!);
  });

  print(combos);
}

