    int i = k ~/ cols;
    int j = k % cols;
    if (distances[i][j] == 0) continue;
    List<List<int>> dirs = [
      [-1, 0], [1, 0], [0, -1], [0, 1]
    ];
    for (List<int> d in dirs) {
      int ni = i + d[0];
      int nj = j + d[1];
      if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
        int cost = distances[i][j] + 1;
        if (cost < distances[ni][nj]) {
          distances[ni][nj] = cost;
        }
      }
    }
  }

  List<List<int>> coords = [];
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (distances[i][j] <= minDist) {
        coords.add([i, j]);
      }
    }
  }

  Map<String, int> result = {};
  for (List<int> p in coords) {
    result[target + ":" + p.join(",")] = 0;
  }
  return result;
}

