Map<String, int> fn0(List<List<String>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) {
    return {};
  }

  int rows = grid.length;
  int cols = grid[0].length;
  List<List<String>> directions = [
    ['N', 'NE', 'E', 'SE'],
    ['S', 'SW', 'W', 'NW']
  ];

  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  List<List<List<int>>> dfsResults = List.generate(rows, (_) => List.filled(cols, [0, 0, 0, 0]));

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (visited[r][c]) {
        continue;
      }

      visited[r][c] = true;

      int edges = 0;
      for (List<String> dir in directions) {
        int nr = r + dir[0].length;
        int nc = c + dir[1].length;
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == grid[r][c]) {
          edges++;
        }
      }

      int score = grid[r][c].length + edges * 2;
      dfsResults[r][c][0] = score;
      dfsResults[r][c][1] = edges;
      dfsResults[r][c][2] = grid[r][c].length;
    }
  }

  Map<String, int> result = {};
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      String cell = grid[r][c];
      int score = dfsResults[r][c][0];
      int edges = dfsResults[r][c][1];
      int len = dfsResults[r][c][2];
      if (!result.containsKey(cell)) {
        result[cell] = {score: 1, edges: 0, len: len};
      } else {
        int oldScore = result[cell]![0];
        int oldEdges = result[cell]![1];
        int oldLen = result[cell]![2];
        if (score > oldScore || (score == oldScore && len > oldLen) || (score == oldScore && edges > oldEdges)) {
          result[cell] = {score: 1, edges: edges, len: len};
        } else if (score == oldScore && len == oldLen && edges > oldEdges) {
          result[cell]![1] = edges;
        }
      }
    }
  }

  return result;
}

