Map<String, int> fn0(List<int> moistureRows) {
  if (moistureRows.isEmpty) {
    return {};
  }

  List<int> sortedMoistureRows = List<int>.from(moistureRows);
  sortedMoistureRows.sort((a, b) {
    int aWet = (a & 0x80) >> 7;
    int bWet = (b & 0x80) >> 7;
    if (aWet != bWet) {
      return aWet.compareTo(bWet);
    }
    int aDry = (a & 0x40) >> 6;
    int bDry = (b & 0x40) >> 6;
    if (aDry != bDry) {
      return aDry.compareTo(bDry);
    }
    return a.compareTo(b);
  });

  int targetSum = 0;
  for (int row in sortedMoistureRows) {
    targetSum += (row & 0x7F) + 1;
  }

  Map<String, int> result = {};
  String state = "";
  int count = 0;

  for (int row in sortedMoistureRows) {
    int rowBits = row & 0x7F;
    int wetCount = 0;
    int dryCount = 0;

    for (int i = 0; i < 7; i++) {
      if ((rowBits & (1 << i)) != 0) {
        wetCount++;
      } else {
        dryCount++;
      }
    }

    int rowSum = wetCount + dryCount;
    if (rowSum == targetSum) {
      if (state.isNotEmpty) {
        result[state] = count;
      }
      state = "";
      count = 1;
    } else if (rowSum < targetSum) {
      state = "Dry";
      dryCount++;
    } else {
      state = "Wet";
      wetCount++;
    }
    count++;
  }

  if (state.isNotEmpty) {
    result[state] = count;
  }
  return result;
}

