  final double cy;
  final double r;

  Circle(this.cx, this.cy, this.r);

  bool contains(Point p) =>
      p.x.abs() + p.y.abs() <= r * r && p.x.abs() - p.y.abs() <= r * r;

  bool contains(Circle other) =>
      contains(other.cx, other.cy, other.r) &&
      contains(other.cx - other.r, other.cy, other.r) &&
      contains(other.cx, other.cy - other.r, other.r) &&
      contains(other.cx - other.r, other.cy - other.r, other.r);

  bool overlaps(Circle other) => other.cx - other.r < cx &&
                                 other.cx + other.r > cx &&
                                 other.cy - other.r < cy &&
                                 other.cy + other.r > cy;

  @override
  String toString() => 'Circle(${cx}, ${cy}, $r)';
}

