  List<List<double>> dp = List.generate(m + 1, (_) => List.filled(m + 1, 0.0));

  for (int i = 0; i <= m; i++) dp[i][0] = i;
  for (int j = 0; j <= m; j++) dp[0][j] = j;

  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= m; j++) {

      int minLen = s1.length < s2.length ? s1.length : s2.length;
      int deletions = dp[i - 1][j] + 1;
      int insertions = dp[i][j - 1] + 1;
      int substitutions = dp[i - 1][j - 1] + (s1[i - 1] != s2[j - 1] ? 1 : 0);

      dp[i][j] = [
        deletions,
        insertions,
        substitutions
      ].reduce((a, b) => a < b ? a : b);
    }
  }

  double cost = dp[m][m];
  print("The cost of aligning $s1 with $s2 is $cost");
}

