    int c = rng.nextInt(cols);
    if (cells[r][c] == 0) {
      cells[r][c] = 1;
      wallCount--;
    }
  }

  void floodFill(int r, int c, int walls) {
    if (r < 0 || r >= rows || c < 0 || c >= cols) {
      return;
    }
    if (cells[r][c] == walls) {
      return;
    }

    cells[r][c] = walls;

    floodFill(r + 1, c, walls);
    floodFill(r - 1, c, walls);
    floodFill(r, c + 1, walls);
    floodFill(r, c - 1, walls);
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (cells[r][c] == 0) {
        floodFill(r, c, 0);
      }
    }
  }

  final rowsWithWalls = List<int>.generate(rows, (_) => List<int>.filled(cols, 1));

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (cells[r][c] == 1) {
        rowsWithWalls[r][c] = 0;
      }
    }
  }

  final numIslands = <int>{};

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (rowsWithWalls[r][c] == 0) {
        numIslands.add(1);
      }
