  for (final size in numIslands) {
    final List<List<int>> coords = [];
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        if (rowsWithWalls[r][c] == 0 && cells[r][c] == 0) {
          coords.add([r, c]);
        }
      }
    }
    islands[size] = coords;
  }

  for (final size in islands.keys) {
    print('Islands of size $size:');
    print(islands[size]!);
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (cells[r][c] == 0) {
        floodFill(r, c, 0);
      }
    }
  }

  final Map<int, List<List<int>>> connectedIslands = {};
  final Set<int> visited = {};

  void dfs(int r, int c, int size) {
    if (r < 0 || r >= rows || c < 0 || c >= cols) {
      return;
    }
    if (cells[r][c] == 1) {
      return;
    }
    if (visited.contains(size)) {
      return;
    }
    visited.add(size);

    cells[r][c] = 1;

    dfs(r + 1, c, size + 1);
    dfs(r - 1, c, size + 1);
    dfs(r, c + 1, size + 1);
    dfs(r, c - 1, size + 1);
  }

  for (int size = 1; size <= numIslands.length; size++) {
    if (numIslands.contains(size)) {
      final List<List<int>> coords = islands[size]!;
      if (coords.isNotEmpty) {
        final int x1 = coords[0][0];
        final int y1 = coords[0][1];
        final int x2 = coords[coords.length - 1][0];
        final int y2 = coords[coords.length - 1][1];
        dfs(y1, x1, size);
        dfs(y1, x2, size);
        dfs(y2, x1, size);
        dfs(y2, x2, size);
        final List<List<int>> rect = [
          [x1, y1],
          [x2, y1],
          [x2, y2],
          [x1, y2],
        ];
        connectedIslands[size] = rect;
      }
    }
  }

  for (final size in connectedIslands.keys) {
    print('Connected islands of size $size:');
    print(connectedIslands[size]!);
  }

  final List<List<double>> distances = List.generate(
    rows,
    (_) => List<double>.filled(cols, 999999999999999999),
  );

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (cells[r][c] == 0) {
        distances[r][c] = 0;
      }
    }
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (cells[r][c] == 1) {
        for (int dr = 0; dr <= 1; dr++) {
          for (int dc = 0; dc <= 1; dc++) {
            int nr = r + dr;
            int nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
              if (distances[r][c] + dr + dc < distances[nr][nc]) {
                distances[nr][nc] = distances[r][c] + dr + dc;
              }
            }
          }
        }
      }
    }
  }

  double minDistance = 999999999999999999;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (distances[r][c] < minDistance) {
        minDistance = distances[r][c];
      }
    }
  }

