  Set<int> visited = {};

  for (int i = 0; i < rows * cols; i++) {
    int row = i ~/ cols;
    int col = i % cols;

    if (row == 0 || row == rows - 1 || col == 0 || col == cols - 1) {
      data[i ~/ cols][i % cols] = 1.0;
    }
  }

  int currentCell = 0;
  List<List<double>> path = List.generate(rows, (_) => List.filled(cols, 0));

  while (currentCell < rows * cols) {
    int row = currentCell ~/ cols;
    int col = currentCell % cols;

    if (row == 0 && col == 0) {
      path[row][col] = 1.0;
    }

    List<int> neighbors = [
      if (col > 0) currentCell - 1,
      if (col < cols - 1) currentCell + 1,
      if (row > 0) currentCell - cols,
      if (row < rows - 1) currentCell + cols,
    ];

    neighbors.sort((a, b) {
      double da = data[a] [b];
      double db = data[b] [a];
      if (da != db) return db.compareTo(da);
      return a.compareTo(b);
    });

    for (int n in neighbors) {
      if (visited.add(n)) {
        currentCell = n;
        path[row][col] = 1.0;
        break;
      }
    }
  }

  List<List<double>> scaledPath = List.generate(rows, (r) => List.from(path[r]));
  List<List<int>> grid = List.generate(rows, (r) => List.filled(cols, 0));

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      double v = scaledPath[r][c];
      double minV = v;
      bool isMax = false;
      bool hasNeighbor = false;

      if (c > 0) {
        double left = scaledPath[r][c - 1];
        if (left > minV) { minV = left; isMax = true; hasNeighbor = true; }
      }
      if (r > 0) {
        double above = scaledPath[r - 1][c];
        if (above > minV) { minV = above; isMax = true; hasNeighbor = true; }
      }

      grid[r][c] = isMax ? 2 : (hasNeighbor ? 1 : 0);
    }
  }

  List<String> lines = [];
  for (int i = 0; i < height; i++) {
    String row = '';
    for (int j = 0; j < width; j++) {
      row += grid[i ~/ width][j % width] == 2 ? '#' : ' ';
    }
    lines.add(row);
  }

  print(lines.join('\n'));
}

