    }
  }

  Stream<int> streamEvenNumbers(int start, int end) async* {
    yield* streamNumbers(start, end);
  }

  Stream<int> streamOddNumbers(int start, int end) async* {
    yield* streamNumbers(start, end);
  }

  Stream<int> streamNumbersWithDelay(int start, int end) async* {
    yield* streamNumbers(start, end);
    await Future.delayed(Duration(milliseconds: 500));
    yield* streamNumbers(start, end);
  }

  Stream<int> combinedStream() async* {
    yield* streamEvenNumbers(1, 10);
    yield* streamOddNumbers(11, 20);
    yield* streamNumbersWithDelay(21, 30);
  }

  print(combinedStream());
}

