  List<T> _heap = [];
  void add(T item) {
    _heap.add(item);
    int index = _heap.length - 1;
    while (index > 0) {
      int parent = (index - 1) >> 1;
      if (item.compareTo(_heap[parent]) < 0) {
        T tmp = _heap[index];
        _heap[index] = _heap[parent];
        _heap[parent] = tmp;
        index = parent;
      } else {
        break;
      }
    }
  }
  T removeFirst() {
    if (_heap.isEmpty) return null;
    T result = _heap[0];
    T last = _heap.removeLast();
    int index = 0;
    while (2 * index + 1 < _heap.length) {
      int left = 2 * index + 1;
      int right = 2 * index + 2;
      if (right < _heap.length && _heap[right].compareTo(_heap[left]) < 0) {
        index = right;
      } else {
        index = left;
      }
      if (_heap[index].compareTo(last) < 0) {
        _heap[index] = last;
      } else {
        break;
      }
    }
    return result;
  }
}

