class BinarySearchTree<T extends Comparable<T>> {
  final Node<T> root;

  BinarySearchTree(this.root);

  void insert(T value) {
    Node<T> current = root;
    Node<T>? parent;
    while (current != null) {
      parent = current;
      if (value.compareTo(current.value) < 0) {
        current = current.children[0];
      } else {
        current = current.children[1];
      }
    }
    if (parent != null) {
      if (value.compareTo(parent.value) < 0) {
        parent.children[0] = Node<T>(value);
      } else {
        parent.children[1] = Node<T>(value);
      }
    } else {
      root = Node<T>(value);
    }
  }

  void printTree(String prefix, int depth) {
    print('$prefix$depth: ${root.value}');
    for (final child in root.children) {
      printTree(prefix + '  ', depth + 1);
    }
  }

  Queue<T> inorderQueue() {
    Queue<T> queue = Queue<T>();
    if (root != null) {
      Queue<T>.addAll(inorderQueue(root.children[0]), queue);
      queue.add(root.value);
      Queue<T>.addAll(inorderQueue(root.children[1]), queue);
    }
    return queue;
  }

  List<T> inorderList() {
    List<T> result = [];
    if (root != null) {
      result += inorderList(root.children[0]);
      result.add(root.value);
      result += inorderList(root.children[1]);
    }
    return result;
  }
}

