class PriorityQueue<T extends Comparable<T>> extends Queue<T> {
  @override
  void add(T item) {
    queue.add(item);
    if (queue.length > 1) {
      int i = queue.length - 1;
      while (i > 0) {
        if (queue[i] == queue[i - 1]) {
          i--;
        } else {
          break;
        }
      }
      if (i > 0) {
        T tmp = queue[i];
        queue[i] = queue[i - 1];
        queue[i - 1] = tmp;
      }
    }
  }

  @override
  T removeFirst() {
    T result = super.removeFirst();
    if (result != null) {
      int j = 0;
      while (j < queue.length) {
        if (queue[j] == result) break;
        j++;
      }
      if (j < queue.length) {
        T tmp = queue[j];
        queue[j] = result;
        result = tmp;
      }
    }
    return result;
  }
}

