Map<String, int> fn0(List<List<String>> grid) {
  if (grid.isEmpty) return {};
  int rows = grid.length;
  int cols = grid[0].length;
  List<List<String>> safe = [];
  List<List<int>> dp = [];
  for (int i = 0; i < rows; i++) {
    List<String> row = [];
    List<int> dpRow = [];
    for (int j = 0; j < cols; j++) {
      if (grid[i][j] == '#') {
        row.add('#');
        dpRow.add(0);
      } else {
        row.add(grid[i][j]);
        dpRow.add(0);
      }
    }
    safe.add(row);
    dp.add(dpRow);
  }
  Map<String, int> best = {};
  for (int r = 0; r < rows; r++) {
    List<int> dpRow = dp[r];
    for (int c = 0; c < cols; c++) {
      if (safe[r][c] == '#') {
        dpRow[c] = 0;
      } else {
        dpRow[c] = 1;
        for (int i = 0; i < c; i++) {
          int p = safe[r][i];
          if (p == '.' && dpRow[i] == 1) {
            dpRow[c] = dpRow[c] > dpRow[i] + 1 ? dpRow[c] : dpRow[i] + 1;
          }
        }
      }
    }
    List<int> bestRow = [];
    int bestSum = 0;
    for (int c = 0; c < cols; c++) {
      if (dpRow[c] > bestSum || (dpRow[c] == bestSum && c > bestSum)) {
        bestSum = dpRow[c];
        bestRow = [bestSum];
      } else if (dpRow[c] == bestSum) {
        bestRow.add(bestSum);
      }
    }
    for (int s = 0; s < bestRow.length; s++) {
      String key = bestRow[s] == 1 ? '1' : bestRow[0];
      best[key] = (best[key] ?? 0) + 1;
    }
