Map<String, int> fn0(List<String> passes) {
  if (passes.isEmpty) return {};
  List<int> nums = [];
  for (var p in passes) {
    int n = p.length;
    nums.add(n);
  }
  int maxLen = 0;
  List<List<int>> dp = List.generate(nums.length, (_) => List.filled(nums.length, 0));
  for (int i = 0; i < nums.length; i++) {
    for (int j = 0; j < i; j++) {
      dp[i][j] = nums[i] > nums[j] ? dp[i - 1][j] + nums[i] : dp[i][j - 1] + nums[j];
      if (dp[i][j] > maxLen) maxLen = dp[i][j];
    }
  }
  Map<String, int> result = {};
  int len = maxLen;
  for (int i = nums.length - 1; i >= 0; i--) {
    if (len == 0) break;
    for (int j = nums.length - 1; j >= 0; j--) {
      if (i == j && len == nums[i]) {
        result[passes[i]] = len;
        len -= nums[i];
        break;
      }
      if (dp[i][j] == len) {
        result[passes[j]] = len;
        len -= nums[j];
        break;
      }
    }
  }
  return result;
}

